import{_ as t,o,c as l,a2 as n}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"太空清除计划","description":"","frontmatter":{},"headers":[],"relativePath":"中层/世界/太空清除计划.md","filePath":"中层/世界/太空清除计划.md","lastUpdated":1787065118000}'),s={name:"中层/世界/太空清除计划.md"};function a(i,r,g,e,h,u){return o(),l("div",null,[...r[0]||(r[0]=[n('<h1 id="太空清除计划" tabindex="-1">太空清除计划 <a class="header-anchor" href="#太空清除计划" aria-label="Permalink to &quot;太空清除计划&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>太空清除计划是神机与维斯塔在间章时期做出的重大战略决策，旨在通过清除地外智慧物种来防止毁灭神在其他星系出现。这一计划体现了神机&quot;掌控危险&quot;核心理念的极端应用，也反映了维斯塔作为变化神的决断力。本文档揭示清除计划的背景、执行方式、相关事件以及对世界观的影响。</p><h2 id="清除计划的背景与动机" tabindex="-1">清除计划的背景与动机 <a class="header-anchor" href="#清除计划的背景与动机" aria-label="Permalink to &quot;清除计划的背景与动机&quot;">​</a></h2><h3 id="根本动机-防止毁灭神扩散" tabindex="-1">根本动机：防止毁灭神扩散 <a class="header-anchor" href="#根本动机-防止毁灭神扩散" aria-label="Permalink to &quot;根本动机：防止毁灭神扩散&quot;">​</a></h3><p><strong>毁灭神的危险性：</strong></p><ul><li><strong>神权特性</strong>：毁灭神权具有极强的破坏性和不可控性</li><li><strong>星系扩散风险</strong>：如果毁灭神在其他星系出现，将造成无法控制的跨星系灾难</li><li><strong>预防性措施</strong>：为避免这种风险，需要采取极端预防措施</li></ul><p><strong>神机与维斯塔的共同决策：</strong></p><ul><li><strong>根本动机</strong>：为防止毁灭神在其他星系出现，神机与维斯塔做出了清除所有地外智慧物种的决定</li><li><strong>责任共担</strong>：两位神明共同承担这一残酷决定的责任</li></ul><h2 id="清除计划的执行方式" tabindex="-1">清除计划的执行方式 <a class="header-anchor" href="#清除计划的执行方式" aria-label="Permalink to &quot;清除计划的执行方式&quot;">​</a></h2><h3 id="清除行动流程" tabindex="-1">清除行动流程 <a class="header-anchor" href="#清除行动流程" aria-label="Permalink to &quot;清除行动流程&quot;">​</a></h3><p><strong>发现与评估：</strong></p><ul><li><strong>监控系统</strong>：利用银河之眼等监控设施监控银河系，发现地外智慧物种</li></ul><p><strong>执行清除：</strong></p><ul><li><strong>主动出击</strong>：与发现的太空文明主动交战</li><li><strong>灭绝策略</strong>：大部分直接灭绝，可能留数据存档</li><li><strong>效率优先</strong>：以最高效率执行清除，避免长期消耗战</li></ul><h3 id="数据保存与记录" tabindex="-1">数据保存与记录 <a class="header-anchor" href="#数据保存与记录" aria-label="Permalink to &quot;数据保存与记录&quot;">​</a></h3><ul><li><strong>数据保存</strong>：大部分直接灭绝，可能留数据存档</li></ul><h2 id="天穹破碎事件" tabindex="-1">天穹破碎事件 <a class="header-anchor" href="#天穹破碎事件" aria-label="Permalink to &quot;天穹破碎事件&quot;">​</a></h2><h3 id="事件背景" tabindex="-1">事件背景 <a class="header-anchor" href="#事件背景" aria-label="Permalink to &quot;事件背景&quot;">​</a></h3><p><strong>太空扩张时机：</strong></p><ul><li><strong>间章登神之后</strong>：神机是在<strong>间章登神之后</strong>才开始大规模向太空扩张的</li><li><strong>前期限制</strong>：登神前，其势力范围局限于地月系以内，受限于资源和技术</li><li><strong>仓促扩张</strong>：急迫地&quot;争时间&quot;，为了布局毁灭神的出现和控制范围，扩张行动较为仓促</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../历史/间章历史">间章历史</a></p></blockquote><p><strong>遭遇外星文明：</strong></p><p><strong>超距作用技术文明：</strong></p><ul><li><strong>意外发现</strong>：急促的扩张导致被一个掌握<strong>超距作用</strong>技术的外星文明发现</li><li><strong>技术震惊</strong>：该文明的技术完全超出了地球科技的认知范围</li></ul><p><strong>超距技术特点：</strong></p><ul><li><strong>基底层应用</strong>：基于对<strong>基底层</strong>的应用，实现了违背相对论的能力：</li><li><strong>超光速移动</strong>：实现了超光速移动，突破了传统物理限制</li><li><strong>超距传输</strong>：实现了空间跃迁式的超距传输</li><li><strong>超距武器</strong>：具有无视距离，指哪打哪的超距武器</li></ul><p><strong>技术对抗劣势：</strong></p><ul><li><strong>防御困境</strong>：超距武器极其诡异，防不胜防。当时地球科技完全无法防御</li><li><strong>技术代差</strong>：暴露了地球科技与先进外星文明之间的巨大代差</li><li><strong>唯一优势</strong>：前传BOSS遗留的<strong>特殊材料</strong>，凭借其超乎想象的强度，能够硬扛几发超距武器的攻击</li></ul><h3 id="太阳系之战" tabindex="-1">太阳系之战 <a class="header-anchor" href="#太阳系之战" aria-label="Permalink to &quot;太阳系之战&quot;">​</a></h3><p><strong>战争性质：</strong></p><ul><li><strong>最大挫败</strong>：这是神机所遭受的<strong>最大挫败之一</strong>，影响了后续的太空战略</li></ul><p><strong>战争过程：</strong></p><ul><li><strong>创造神权应用</strong>：神机利用其创造神权（可先有结果再补过程，甚至紧急制造悖论）以诡异的速度进步和反击</li><li><strong>战争范围</strong>：外星文明入侵太阳系，从冥王星一路打到地球轨道，神机再将战线推回冥王星</li><li><strong>激烈对抗</strong>：战争范围横跨整个太阳系，形势一度极为危急</li></ul><p><strong>结局与影响：</strong></p><ul><li><strong>成功击退</strong>：神机最终在<strong>地月系</strong>击退了外星入侵者，将其势力彻底赶出太阳系</li><li><strong>战略调整</strong>：此后，她向宇宙的探索变得<strong>更加谨慎</strong>，不再冒进</li><li><strong>技术应用</strong>：战后，月球武器平台的光束融合了<strong>超距作用</strong>原理</li></ul><h3 id="事件表象与真相" tabindex="-1">事件表象与真相 <a class="header-anchor" href="#事件表象与真相" aria-label="Permalink to &quot;事件表象与真相&quot;">​</a></h3><p><strong>福瑞世界的认知：</strong></p><ul><li><strong>发生时间</strong>：建国22年</li><li><strong>表象描述</strong>：天空忽然破碎，变成一块块时不时变黑的巨大六边形，一块六边形以及一个大约是圆柱体或长方形的东西掉了下来</li><li><strong>短暂现象</strong>：焰种短暂出现</li><li><strong>最终结果</strong>：灾难被神明解决，焰种再没有人见过</li></ul><p><strong>中层真相：</strong></p><p><strong>天穹破碎的真实由来：</strong></p><ul><li><strong>飞船坠毁</strong>：战斗中，一艘外星飞船坠毁，撞上了神机为掩饰自己改造太阳系动作而制造的<strong>天幕</strong></li><li><strong>事件形成</strong>：形成&quot;天穹破碎&quot;事件，被福瑞种族误解为天灾</li><li><strong>焰种的结局</strong>：坠毁飞船上的外星种族——<strong>焰种</strong>（接触氧气即自燃，因死亡时燃烧被贬称为&quot;焰种&quot;）——短暂出现后，残部逃窜伪装当地原住民企图生存延续，但太空战争结束后被神机的精灵部队搜查猎杀殆尽——因为不能让他们牵扯到故事里</li></ul><p><strong>天幕的作用：</strong></p><ul><li><strong>掩饰功能</strong>：神机制造天幕以掩饰自己对太阳系的改造动作</li><li><strong>模块化设计</strong>：由巨大的六边形模块构成，六边形是人工天幕的原生几何结构</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./太空巨构">太空巨构</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../人物/神机">神机</a></li><li><a href="./../人物/维斯塔">维斯塔</a></li><li><a href="./太空巨构">太空巨构</a></li><li><a href="./../历史/间章历史">间章历史</a></li><li><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></li><li><a href="./../../底层/规则/基底层与现实世界" class="layer-link" data-layer="底层">基底层与现实世界</a></li><li><a href="./神机谋划">神机谋划</a></li></ul><hr>',49)])])}const c=t(s,[["render",a]]);export{p as __pageData,c as default};
